/// GPU pixel / block-compression format.
///
/// Uncompressed formats store one pixel per "block"; BCn formats store a 4×4 pixel tile per block.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum PixelFormat {
    /// 8-bit single channel (1 byte per pixel).
    R8 = 0,
    /// 16-bit single channel UNORM (2 bytes per pixel).
    R16 = 1,
    /// Single-precision single channel (4 bytes per pixel).
    R32F = 2,
    /// 8-bit dual channel (2 bytes per pixel).
    RG8 = 3,
    /// 16-bit dual channel UNORM (4 bytes per pixel).
    RG16 = 4,
    /// Single-precision dual channel (8 bytes per pixel).
    RG32F = 5,
    /// 8-bit RGBA (4 bytes per pixel).
    RGBA8 = 6,
    /// 16-bit RGBA UNORM (8 bytes per pixel).
    RGBA16 = 7,
    /// Single-precision RGBA (16 bytes per pixel).
    RGBA32F = 8,
    /// DXT1 – 8 bytes per 4×4 block (RGB + optional 1-bit alpha).
    BC1 = 9,
    /// DXT3 – 16 bytes per 4×4 block (explicit 4-bit alpha).
    BC2 = 10,
    /// DXT5 – 16 bytes per 4×4 block (interpolated alpha).
    BC3 = 11,
    /// Single-channel – 8 bytes per 4×4 block.
    BC4 = 12,
    /// Dual-channel – 16 bytes per 4×4 block.
    BC5 = 13,
    /// HDR RGB – 16 bytes per 4×4 block (half-float output).
    BC6H = 14,
    /// High-quality RGBA – 16 bytes per 4×4 block.
    BC7 = 15,
}

impl TryFrom<i32> for PixelFormat {
    type Error = crate::Error;
    fn try_from(v: i32) -> Result<Self, crate::Error> {
        match v {
            0 => Ok(PixelFormat::R8),
            1 => Ok(PixelFormat::R16),
            2 => Ok(PixelFormat::R32F),
            3 => Ok(PixelFormat::RG8),
            4 => Ok(PixelFormat::RG16),
            5 => Ok(PixelFormat::RG32F),
            6 => Ok(PixelFormat::RGBA8),
            7 => Ok(PixelFormat::RGBA16),
            8 => Ok(PixelFormat::RGBA32F),
            9 => Ok(PixelFormat::BC1),
            10 => Ok(PixelFormat::BC2),
            11 => Ok(PixelFormat::BC3),
            12 => Ok(PixelFormat::BC4),
            13 => Ok(PixelFormat::BC5),
            14 => Ok(PixelFormat::BC6H),
            15 => Ok(PixelFormat::BC7),
            other => Err(crate::Error::UnknownEnum {
                name: "PixelFormat",
                value: other,
            }),
        }
    }
}

/// Dimensionality / topology of a texture resource.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum TextureType {
    /// Standard 2D image (1 layer).
    Texture2D = 0,
    /// Volume texture (depth > 1, depth halves each mip).
    Texture3D = 1,
    /// Cube map (6 square layers, one per face).
    TextureCube = 2,
    /// Array of 2D images (arraySize layers).
    Texture2DArray = 3,
    /// Array of cube maps (6 × arraySize layers).
    TextureCubeArray = 4,
}

impl TryFrom<i32> for TextureType {
    type Error = crate::Error;
    fn try_from(v: i32) -> Result<Self, crate::Error> {
        match v {
            0 => Ok(TextureType::Texture2D),
            1 => Ok(TextureType::Texture3D),
            2 => Ok(TextureType::TextureCube),
            3 => Ok(TextureType::Texture2DArray),
            4 => Ok(TextureType::TextureCubeArray),
            other => Err(crate::Error::UnknownEnum {
                name: "TextureType",
                value: other,
            }),
        }
    }
}

